const Question = ({ questionText, answerChoices, onAnswerSelected }) => {
    return (
        <div className="question-container">
            <h2>{questionText}</h2>
            <ul>
                {answerChoices.map((choice, index) => (
                    <li key={index} onClick={() => onAnswerSelected(index)}>
                        {choice}
                    </li>
                ))}
            </ul>
        </div>
    );
};

export default Question;
